if (inputs.architecture !== 'LlamaForCausalLM') throw new Error('Expected native LlamaForCausalLM');
if (inputs.parameter_count !== 78144 || inputs.parameter_tensors !== 21) throw new Error('Unexpected Llama dimensions or weights');
const modules = inputs.modules || [];
for (const type of ['LlamaDecoderLayer','LlamaAttention','LlamaMLP','LlamaRMSNorm','LlamaRotaryEmbedding']) {
  if (!modules.some(m => m.type === type)) throw new Error('Missing native component: ' + type);
}
const p = inputs.parameters;
for (let i = 0; i < 2; i++) {
  for (const part of ['self_attn.q_proj.weight','self_attn.k_proj.weight','self_attn.v_proj.weight','self_attn.o_proj.weight','mlp.gate_proj.weight','mlp.up_proj.weight','mlp.down_proj.weight']) {
    if (!p.some(t => t.name === `model.layers.${i}.${part}`)) throw new Error('Missing projection ' + part);
  }
}
console.log('Verified actual native Llama module and tensor inventory');
return {value:{verified:true,architecture:inputs.architecture,parameters:inputs.parameter_count,tensors:inputs.parameter_tensors,decoder_layers:2,query_heads:4,kv_heads:2,rope:true,normalization:'RMSNorm',feed_forward:'SwiGLU'}};
